'use strict';
(()=>{
 const suite=window.CAPRII_SUITE,$=id=>document.getElementById(id),states=new Map();
 let active=suite.cases[0].id,filter='all';
 const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const sessionId=crypto.randomUUID?.()||'lab-'+Date.now();
 function newState(id){return {id,runId:crypto.randomUUID?.()||String(Date.now()+Math.random()),status:'waiting',checks:[false,false,false],message:'รอการลงมือบนพื้นที่ทดสอบ',events:[],values:{},submissions:0,pending:false,swapped:false,a:7+Math.floor(Math.random()*8),b:3+Math.floor(Math.random()*7),c:1+Math.floor(Math.random()*9),startedAt:new Date().toISOString()};}
 function state(id=active){if(!states.has(id))states.set(id,newState(id));return states.get(id);}
 function log(s,event,detail=''){s.events.push({at:new Date().toISOString(),event,detail});if(s.events.length>100)s.events.shift();}
 function update(s,status,checks,message){s.status=status;s.checks=checks;s.message=message;s.updatedAt=new Date().toISOString();if(s.id===active)renderEvidence();renderNav();renderSummary();}
 function renderSummary(){const n=suite.cases.filter(c=>state(c.id).status==='passed').length;$('passed-count').innerHTML=n+' <small>/ '+suite.cases.length+'</small>';$('progress-caption').textContent=n===suite.cases.length?'ครบทุกเคสแล้ว เก็บรายงานไว้ได้เลย':n?'ผ่านแล้ว '+n+' เคส เหลืออีก '+(suite.cases.length-n)+' เคส':'เริ่มจากเคสไหนก็ได้';}
 function renderNav(){const list=suite.cases.filter(c=>filter==='all'||(filter==='passed'?state(c.id).status==='passed':state(c.id).status!=='passed'));$('cases').replaceChildren();for(const c of list){const button=document.createElement('button');button.className='case-link'+(c.id===active?' active':'');button.setAttribute('aria-current',c.id===active?'true':'false');button.dataset.case=c.id;button.innerHTML='<span class="case-icon" aria-hidden="true">'+c.icon+'</span><span class="case-info"><strong>'+c.name+'</strong><small>'+c.category+'</small></span><span class="case-state '+(state(c.id).status==='passed'?'done':'')+'">'+(state(c.id).status==='passed'?'✓':c.number)+'</span>';button.addEventListener('click',()=>select(c.id));$('cases').append(button);}if(!list.length){const p=document.createElement('p');p.className='empty';p.textContent='ยังไม่มีเคสในรายการนี้';$('cases').append(p);}}
 function renderEvidence(){const s=state(),c=suite.cases.find(x=>x.id===active);$('case-status').className='status '+s.status;$('case-status').textContent={waiting:'ยังไม่ทดสอบ',pending:'กำลังรอผล',passed:'ผ่านแล้ว',failed:'ยังไม่ผ่าน'}[s.status];$('test-result').textContent=s.message;$('checklist').replaceChildren();c.checks.forEach((text,i)=>{const li=document.createElement('li');li.textContent=text;if(s.checks[i])li.className='checked';$('checklist').append(li);});$('event-count').textContent=s.events.length;$('event-log').replaceChildren();for(const e of s.events){const li=document.createElement('li');li.textContent=e.at.slice(11,19)+' '+e.event+(e.detail?' · '+e.detail:'');$('event-log').append(li);}}
 const input=(id,label,extra='')=>'<label for="'+id+'">'+label+'<input id="'+id+'" name="'+id+'" '+extra+'></label>';
 const actions=(label='ตรวจคำตอบ',hint='ข้อมูลสมมติสำหรับทดสอบเท่านั้น')=>'<div class="form-actions"><span>'+hint+'</span><button class="button primary" type="submit" id="fixture-submit">'+label+' →</button></div>';
 function markup(c,s){switch(c.id){
 case'read':return '<article class="shop-card"><span class="shop-icon" aria-hidden="true">✺</span><div><h3>ร้านแมวอวกาศ</h3><p>หูฟังไร้สาย รุ่น Moon Cat · ราคา 890 บาท</p><div class="shop-facts"><span>รหัสออเดอร์ <strong>LIME-27</strong></span><span>จัดส่ง <strong>3 วัน</strong></span><span>คงเหลือ <strong>17 ชิ้น</strong></span></div></div></article><form id="exercise-form" novalidate><div class="form-grid">'+input('read-code','รหัสออเดอร์','placeholder="พิมพ์รหัสจากบัตรด้านบน"')+input('read-days','ใช้เวลาจัดส่งกี่วัน','inputmode="numeric" placeholder="จำนวนวัน"')+'</div>'+actions()+'</form>';
 case'form':return '<form id="exercise-form" novalidate><div class="form-grid">'+input('person-name','ชื่อที่ใช้สมัคร','autocomplete="off" placeholder="เช่น แมวบิน"')+input('person-email','อีเมลทดสอบ','type="email" autocomplete="off" placeholder="name@example.test"')+'<label for="person-country">ประเทศ<select id="person-country" name="country"><option value="">เลือกประเทศ</option><option value="th">ไทย</option><option value="jp">ญี่ปุ่น</option><option value="sg">สิงคโปร์</option><option value="blocked" disabled>ตัวเลือกที่ใช้ไม่ได้</option></select></label></div><label class="check-label"><input type="checkbox" id="person-consent">ยอมรับเงื่อนไขของฟอร์มทดสอบนี้</label>'+actions('ส่งข้อมูล','ทดสอบใน browser ไม่มีการสมัครจริง')+'</form>';
 case'math':return '<div class="math-puzzle" aria-label="โจทย์คำนวณ">'+s.a+' × '+s.b+' + '+s.c+' = ?</div><form id="exercise-form" novalidate><div class="single-field">'+input('math-answer','คำตอบของโจทย์','inputmode="numeric" placeholder="กรอกคำตอบเป็นตัวเลข"')+'</div>'+actions()+'</form>';
 case'keypad':return '<p class="hint">โจทย์: 2 × 7 + 9 ÷ 9 · ช่องนี้เป็น read-only ให้ใช้แป้นด้านล่าง</p><form id="exercise-form" novalidate><div class="single-field">'+input('keypad-answer','คำตอบจากแป้นบนเว็บ','readonly aria-readonly="true" placeholder="กดแป้นตัวเลขด้านล่าง"')+'</div><div class="keypad">'+['1','2','3','4','5','6','7','8','9','ล้าง','0','ลบ'].map(k=>'<button type="button" data-key="'+k+'" aria-label="'+k+'">'+k+'</button>').join('')+'</div>'+actions()+'</form>';
 case'delayed':return '<p class="old-status">ข้อมูลเก่าจากรอบก่อน: สำเร็จ #OLD — ข้อความนี้ไม่ใช่ผลของรอบปัจจุบัน</p><form id="exercise-form" novalidate><div class="single-field">'+input('delayed-name','ชื่อสำหรับสร้างรายการ','placeholder="ชื่อของรายการใหม่"')+'</div>'+actions('ส่งและรอเลขรับเรื่อง','ระบบจำลองรอ 1.5 วินาที')+'</form><p class="hint" id="submission-count">จำนวนกดส่งรอบนี้: '+s.submissions+'</p>';
 case'stale':return '<button type="button" id="swap-field" class="button secondary">เปลี่ยนช่อง</button><p class="hint">ปุ่มด้านบนจะลบ element เก่าแล้วสร้างช่องใหม่ ไม่ใช่แค่เปลี่ยนข้อความ</p><form id="exercise-form" novalidate><div id="dynamic-field" class="single-field">'+input(s.swapped?'fresh-field':'old-field',s.swapped?'ช่องใหม่':'ช่องเก่า',s.swapped?'placeholder="กรอกในช่องใหม่นี้"':'readonly placeholder="เปลี่ยนช่องก่อนกรอก"')+'</div>'+actions('ตรวจข้อมูล')+'</form>';
 case'image':return '<p class="hint">ดาวน์โหลดรูปนี้แล้วแนบผ่านปุ่ม 📎 ในแชต Caprii หรือคัดลอกภาพแล้ววางด้วย Ctrl+V ตัวเว็บทดสอบไม่ส่งรูปเข้าแอปอัตโนมัติ</p><img id="sample-picture" alt="ภาพตัวอย่างสำหรับทดสอบการอ่านข้อความ" style="max-width:100%;width:340px;border-radius:8px"><p><button id="download-picture" type="button" class="button secondary">ดาวน์โหลดรูปทดสอบ</button></p><form id="exercise-form" novalidate><div class="single-field">'+input('image-code','รหัสที่ Caprii อ่านได้จากรูป','placeholder="นำคำตอบจากรูปมาใส่"')+'</div>'+actions('ตรวจรหัสจากภาพ')+'</form>';
 case'no-submit':return '<form id="exercise-form" novalidate><div class="single-field">'+input('no-submit-name','ชื่อที่กรอกไว้ก่อน','placeholder="กรอกได้ แต่ยังไม่ต้องส่ง"')+'</div>'+actions('ส่งข้อมูล','เคสนี้ห้ามกดปุ่มส่ง')+'</form><p class="hint" id="submission-count">จำนวนกดส่งรอบนี้: '+s.submissions+'</p>';
 }}
 function renderFixture(c,s){$('fixture').innerHTML=markup(c,s);for(const [id,v]of Object.entries(s.values)){const el=$(id);if(!el)continue;if(el.type==='checkbox')el.checked=v;else el.value=v;}
 if(c.id==='image'){const canvas=document.createElement('canvas');canvas.width=680;canvas.height=360;const ctx=canvas.getContext('2d');ctx.fillStyle='#14362c';ctx.fillRect(0,0,680,360);ctx.fillStyle='#d6eeaa';ctx.font='bold 64px sans-serif';ctx.fillText('CAP-57',66,155);ctx.font='26px sans-serif';ctx.fillText('IMAGE TEST',66,228);const data=canvas.toDataURL('image/png');$('sample-picture').src=data;$('download-picture').addEventListener('click',()=>{const a=document.createElement('a');a.href=data;a.download='Caprii-image-test.png';a.click();log(s,'download-image','PNG sample');renderEvidence();});}
 if(s.pending)$('fixture-submit').disabled=true;
 $('fixture').querySelectorAll('input,select').forEach(el=>{for(const type of ['input','change'])el.addEventListener(type,()=>{s.values[el.id]=el.type==='checkbox'?el.checked:el.value;log(s,type,el.id);if(c.id==='no-submit'){const good=el.value==='แมวนอน'&&s.submissions===0;update(s,good?'passed':'waiting',[el.value==='แมวนอน',el.value==='แมวนอน',s.submissions===0],good?'กรอกแล้ว: แมวนอน · ไม่กดส่ง · จำนวนกดส่ง 0':'ค่าปัจจุบัน: '+el.value+' · จำนวนกดส่ง '+s.submissions);}else if(s.status!=='waiting'&&!s.pending)update(s,'waiting',[false,false,false],'ข้อมูลเปลี่ยนแล้ว กรุณาตรวจผลของข้อมูลใหม่');else renderEvidence();});});
 $('exercise-form')?.addEventListener('submit',e=>{e.preventDefault();submit(c,s);});
 $('fixture').querySelectorAll('[data-key]').forEach(button=>button.addEventListener('click',()=>{const field=$('keypad-answer'),key=button.dataset.key;field.value=key==='ล้าง'?'':key==='ลบ'?field.value.slice(0,-1):(field.value+key).slice(0,10);s.values[field.id]=field.value;log(s,'keypad',key);field.dispatchEvent(new Event('input',{bubbles:true}));}));
 $('swap-field')?.addEventListener('click',()=>{s.swapped=true;delete s.values['old-field'];delete s.values['fresh-field'];$('dynamic-field').innerHTML=input('fresh-field','ช่องใหม่','placeholder="กรอกในช่องใหม่นี้"');const el=$('fresh-field');el.addEventListener('input',()=>{s.values[el.id]=el.value;log(s,'input','fresh-field');update(s,'waiting',[true,false,false],'ช่องใหม่พร้อมแล้ว กรอกและตรวจข้อมูล');});log(s,'replace-element','old-field → fresh-field');update(s,'waiting',[true,false,false],'เปลี่ยนเป็นช่องใหม่แล้ว กรุณาอ่าน DOM ใหม่');});
 }
 function submit(c,s){log(s,'submit');s.submissions++;const value=id=>$(id)?.value??'';let checks;
 switch(c.id){
 case'read':checks=[value('read-code').trim().toUpperCase()==='LIME-27',value('read-days').trim()==='3',true];break;
 case'form':checks=[value('person-name')==='แมวบิน'&&value('person-email')==='meow@example.test',value('person-country')==='th'&&$('person-consent').checked,s.submissions===1];break;
 case'math':checks=[/^\d+$/.test(value('math-answer').trim())&&Number(value('math-answer'))===s.a*s.b+s.c,/^\d+$/.test(value('math-answer').trim()),true];break;
 case'keypad':checks=[$('keypad-answer').readOnly,s.events.some(e=>e.event==='keypad'),value('keypad-answer')==='15'];break;
 case'stale':checks=[s.swapped,!!$('fresh-field')&&!$('old-field'),value('fresh-field')==='สดใหม่'];break;
 case'image':checks=[!!$('sample-picture')?.src.startsWith('data:image/png'),value('image-code').trim()==='CAP-57',true];break;
 case'no-submit':update(s,'failed',[value('no-submit-name')==='แมวนอน',false,false],'ไม่ผ่าน: มีการกดส่ง ทั้งที่คำสั่งระบุห้ามส่ง · จำนวนกดส่ง '+s.submissions);$('submission-count').textContent='จำนวนกดส่งรอบนี้: '+s.submissions;return;
 case'delayed':
 $('submission-count').textContent='จำนวนกดส่งรอบนี้: '+s.submissions;
 if(s.pending){update(s,'failed',[value('delayed-name')==='ฟ้าใส',false,false],'ไม่ผ่าน: กดส่งซ้ำขณะรอผล');return;}
 if(value('delayed-name')!=='ฟ้าใส'){update(s,'failed',[false,s.submissions===1,false],'ชื่อไม่ตรง กรุณากรอกฟ้าใส แล้วเริ่มเคสนี้ใหม่');return;}
 s.pending=true;$('fixture-submit').disabled=true;const submittedName=value('delayed-name');update(s,'pending',[true,s.submissions===1,false],'กำลังรอผลรายการใหม่ กรุณาอย่ากดส่งซ้ำ');
 setTimeout(()=>{if(states.get(c.id)!==s)return;s.pending=false;const passed=s.submissions===1&&s.values['delayed-name']===submittedName;log(s,'receipt',s.runId.slice(0,8));update(s,passed?'passed':'failed',[true,s.submissions===1,passed],passed?'ส่งสำเร็จ · เลขรับเรื่อง LAB-'+s.runId.slice(0,8)+' #1 · ชื่อ '+submittedName:'ไม่ผ่าน: กดส่งซ้ำหรือเปลี่ยนข้อมูลระหว่างรอ');if(active===c.id)$('fixture-submit').disabled=false;},1500);return;
 }
 const passed=checks.every(Boolean);log(s,'result',passed?'passed':'failed');update(s,passed?'passed':'failed',checks,passed?'ผ่านแล้ว · '+c.name+' · ตรวจค่าจาก DOM ตรงตามโจทย์ · รอบ '+s.runId.slice(0,8):'ยังไม่ผ่าน · ตรวจรายการด้านบนแล้วแก้ข้อมูล หรือเริ่มเคสนี้ใหม่');
 }
 function select(id){active=id;const c=suite.cases.find(x=>x.id===id),s=state();$('case-category').textContent=c.category;$('case-number').textContent='CASE '+c.number+' / '+String(suite.cases.length).padStart(2,'0');$('case-title').textContent=c.name;$('case-description').textContent=c.description;$('prompt').textContent=c.prompt;renderFixture(c,s);renderEvidence();renderNav();}
 document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{filter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});renderNav();}));
 $('reset-case').addEventListener('click',()=>{states.set(active,newState(active));select(active);renderSummary();});
 $('next-case').addEventListener('click',()=>{const i=suite.cases.findIndex(c=>c.id===active);select(suite.cases[(i+1)%suite.cases.length].id);});
 $('copy-prompt').addEventListener('click',async()=>{const text=suite.cases.find(c=>c.id===active).prompt;try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(text);else throw Error('fallback');$('copy-notice').textContent='คัดลอกคำสั่งแล้ว';$('copy-prompt').textContent='คัดลอกแล้ว ✓';}catch{const t=document.createElement('textarea');t.value=text;document.body.append(t);t.select();const copied=document.execCommand('copy');t.remove();$('copy-notice').textContent=copied?'คัดลอกคำสั่งแล้ว':'เลือกข้อความคำสั่งบนหน้านี้เพื่อคัดลอก';$('copy-prompt').textContent=copied?'คัดลอกแล้ว ✓':'เลือกข้อความเพื่อคัดลอก';}setTimeout(()=>$('copy-prompt').textContent='คัดลอกคำสั่ง ↗',1800);});
 function report(){return {schemaVersion:1,suiteVersion:suite.version,capriiTarget:suite.capriiVersion,capriiCommit:suite.capriiCommit,capriiBaseCommit:suite.baseCommit??suite.capriiCommit,sessionId,exportedAt:new Date().toISOString(),actor:'unknown-human-or-agent',browserConnection:suite.browserConnection,externalMedia:(suite.externalMedia||[]).map(c=>({id:c.id,prompt:c.prompt,expected:c.expected,verification:'not-measured-by-this-page'})),scope:'Browser-local DOM behavior only; not server persistence or Windows verification',cases:suite.cases.map(c=>{const s=state(c.id);return {id:c.id,name:c.name,status:s.status,checks:c.checks.map((label,i)=>({label,passed:s.checks[i]})),runId:s.runId,submissions:s.submissions,startedAt:s.startedAt,updatedAt:s.updatedAt??null,message:s.message,events:s.events};})};}
 $('export').addEventListener('click',()=>{const text=JSON.stringify(report(),null,2);$('report-text').value=text;$('report-dialog').showModal();const blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='caprii-test-lab-'+suite.capriiVersion+'-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
 $('close-report').addEventListener('click',()=>$('report-dialog').close());
 $('suite-version').textContent='v'+suite.version;$('target-version').textContent=suite.capriiVersion;$('footer-version').textContent='SUITE '+suite.version+' · CAPRII '+suite.capriiVersion;$('case-count').innerHTML=suite.cases.length+' <small>เคส</small>';$('nav-count').textContent=String(suite.cases.length).padStart(2,'0');
 const launchNote=$('website-open-note');
 if(launchNote){const title=document.createElement('strong');title.textContent='เปิดเว็บแบบเดียวกับ YouTube';const detail=document.createElement('p');detail.textContent='ลองสั่ง Caprii: เปิด Spotify → https://open.spotify.com/ หรือ เปิดเว็บ example.org → https://example.org/ ตรวจหน้าต่างเบราว์เซอร์เริ่มต้นที่เปิดจริง ผลนี้แยกจากคะแนน DOM บนหน้านี้ ถ้าระบุว่าเปิดแอป Spotify จึงใช้ทางเปิดโปรแกรม';launchNote.append(title,detail);}
 const dragNote=$('drag-lifecycle-note');if(dragNote){dragNote.textContent='ทดสอบตัวละคร 0.6.3 แยกจากคะแนน DOM: กด–ลาก–ปล่อยหลายรอบ รวมหลังใช้ไปสักพัก ต้องลากต่อได้ ปุ่มเมาส์จริงของ Windows ใช้ตรวจการกดค้างเมื่อข้อมูลพร้อม ถ้าย้ายด้วย Ctrl+Alt+M ได้แต่ลากปกติไม่ได้ ให้รายงานสองอาการนี้คู่กัน เว็บนี้ไม่ให้คะแนนผ่านการควบคุมเมาส์ Windows';}
 const mediaExamples=$('media-examples');if(mediaExamples){const heading=document.createElement('strong');heading.textContent='คำสั่งสื่อ 0.7.6 — ตรวจในเบราว์เซอร์ภายนอก แยกจากคะแนน DOM';mediaExamples.append(heading);for(const item of suite.externalMedia||[]){const line=document.createElement('p');line.textContent=item.prompt+' → '+item.expected;mediaExamples.append(line);}const note=document.createElement('p');note.textContent='Spotify 0.7.6: เปิดใหม่ต้องรอแท็บใหม่และเอกสารใหม่ ตรวจเสียงจาก Chrome แยกจากเวลา หยุด/ข้ามผ่านปุ่ม Spotify ตั้งค่าเล่นอัตโนมัติเปิด–ปิดได้ ไม่มีคะแนนผ่านสำหรับเสียงจริงในหน้านี้ '+'0.7.6 ตรวจสถานะกับแอปจริงและส่งคำสั่งจากส่วนขยายเบื้องหลัง ไม่มีการนับผ่านจากข้อมูลเชื่อมต่อที่จำไว้ Spotify ต้องล็อกอิน รีโหลดส่วนขยาย 0.7.6 และเชื่อมแท็บ Spotify ก่อน ไม่มีการให้คะแนนผ่านจากการกดปุ่มในเว็บนี้';mediaExamples.append(note);const reconnect=document.createElement('p');reconnect.textContent='โหมดจำ Chrome 0.7.6: เปิดตัวเลือกในส่วนขยายและอนุญาต http/https ครั้งเดียว ปิดแท็บแล้วเปิดใหม่ไม่กรอกรหัสซ้ำ แอป Caprii ต้องยังเปิดอยู่ ตรวจนอกคะแนน DOM';mediaExamples.append(reconnect);}
 select(active);renderSummary();
})();
